mapper.select:
select  from permission_definitions
where permission_code in #{code}
order by permission_code

mapper.update:
update permission_catalog_revision_aliases set canonical_permission_code=#{row.canonicalPermissionCode},
  alias_type=#{row.aliasType},valid_from=#{row.validFrom},valid_until=#{row.validUntil},reason=#{row.reason},
  version=#{row.version}
where revision_id=#{row.revisionId}::uuid and alias_code=#{row.aliasCode} and version=#{expectedVersion}

update permission_catalog_revisions set status='PUBLISHED',content_hash=#{contentHash},published_at=#{at},
  published_by=#{actorId},version=version+1
where revision_id=#{revisionId}::uuid and status='DRAFT' and version=#{expectedVersion}

update permission_entry_point_inventory set owner_module=#{row.ownerModule},authority_state=#{row.authorityState},
  target_permission_code=nullif(#{row.targetPermissionCode},''),legacy_authority_type=nullif(#{row.legacyAuthorityType},''),
  legacy_authorities=#{row.legacyAuthorities}::jsonb,resource_type=#{row.resourceType},resource_resolver_id=#{row.resourceResolverId},
  exemption_reason=nullif(#{row.exemptionReason},''),migration_deadline=#{row.migrationDeadline},last_verified_at=#{row.lastVerifiedAt}
where entry_point_id=#{row.entryPointId} and version=#{expectedVersion}

update permission_legacy_authority_mappings set target_permission_code=nullif(#{row.targetPermissionCode},''),owner_module=#{row.ownerModule},
  status=#{row.status},migration_deadline=#{row.migrationDeadline},notes=#{row.notes}
where mapping_id=#{row.mappingId} and version=#{expectedVersion}

mapper.select:
select  from permission_application_manifest_readiness
order by case status when 'ACTIVE' then 0 when 'REGISTERING' then 1 else 2 end,registered_at desc,manifest_id desc
limit #{limit}

select  from permission_shadow_observation_readiness
where (#{tenantId}='' or tenant_id=#{tenantId}) and (#{domainCode}='' or domain_code=#{domainCode}) and (#{category}='' or mismatch_category=#{category})
order by cutover_blocker desc,compared_at desc limit #{limit}

select  from permission_shadow_mismatch_cases c
where (#{tenantId}='' or c.source_tenant_id=#{tenantId}) and (#{domainCode}='' or c.domain_code=#{domainCode}) and (#{status}='' or c.status=#{status})
order by case c.severity when 'CRITICAL' then 1 when 'HIGH' then 2 when 'MEDIUM' then 3 else 4 end,c.sla_due_at,c.updated_at desc limit #{limit}

mapper.update:
update rbac_roles set role_name=#{row.roleName},description=#{row.description},status=#{row.status},
  updated_at=#{row.updatedAt},updated_by=#{row.updatedBy},version=#{row.version}
where role_id=#{row.roleId} and tenant_id is not distinct from #{row.tenantId} and version=#{expectedVersion}

update rbac_principal_role_bindings set
  role_id=#{row.roleId},scope_type=#{row.scopeType},scope_id=#{row.scopeId},
  effective_at=#{row.effectiveAt},expires_at=#{row.expiresAt},status=#{row.status},
  revoked_at=#{row.revokedAt},revoked_by=#{row.revokedBy},version=#{row.version}
where binding_id=#{row.bindingId} and tenant_id=#{row.tenantId} and version=#{expectedVersion}

mapper.select:
select  from rbac_critical_change_approvals
where tenant_id is not distinct from nullif(#{tenantId},'INSTANCE') and (#{status}='' or status=#{status})
order by requested_at desc,approval_id desc limit #{limit}

mapper.update:
update rbac_critical_change_approvals set status=#{row.status},approver_id=nullif(#{row.approverId},''),
  decision_reason=nullif(#{row.decisionReason},''),decided_at=#{row.decidedAt},consumed_at=#{row.consumedAt},
  version=#{row.version}
where tenant_id is not distinct from nullif(#{row.tenantId},'INSTANCE') and approval_id=#{row.approvalId} and version=#{expectedVersion}
